/** Every entry, flattened, with its theme attached — used by the search. */
export function allWords(themes) {
  const out = [];
  for (const theme of (themes || VOCAB_THEMES)) {
    for (const word of (VOCAB[theme.id] || [])) {
      out.push(Object.assign({ themeId: theme.id, themeName: theme.name, tone: theme.tone }, word));
    }
  }
  return out;
}

